def empty_uid_to_null(apps, schema_editor):
    """An unknown uid was stored as "": it becomes NULL, so several devices without uid respect `unique`."""
    Device = apps.get_model("hardware", "Device")
    Device.objects.filter(uid="").update(uid=None)


def null_uid_to_empty(apps, schema_editor):
    """Reverse step: NULL goes back to "" (breaks `unique` if several devices have no uid)."""
    Device = apps.get_model("hardware", "Device")
    Device.objects.filter(uid__isnull=True).update(uid="")


